local BilliardMaker = {}
local PRODUCTS = {
    simple_wood_billiard = { name = "Preprost leseni biljard", woodCost = 4, woolCost = 2, time = 7, cost = 200, happiness = 4, prestige = 3, description = "Preprost leseni biljard za krčme." },
    felt_covered_billiard = { name = "Filcnopokrita biljard", woodCost = 4, woolCost = 3, leatherCost = 1, time = 10, cost = 480, happiness = 5, prestige = 7, description = "Filcnopokrita biljard za trgovce." },
    silver_pocket_billiard = { name = "Srebrnoreznična biljard", woodCost = 4, silverCost = 1, woolCost = 3, leatherCost = 1, time = 13, cost = 1100, happiness = 6, prestige = 14, description = "Srebrnoreznična biljard za plemiče." },
    gold_trimmed_billiard = { name = "Zlatookrasna biljard", woodCost = 4, goldCost = 1, silverCost = 1, woolCost = 3, leatherCost = 1, time = 17, cost = 2500, happiness = 7, prestige = 22, description = "Zlatookrasna biljard za visoke plemiče." },
    jewel_set_billiard = { name = "Draguljasta biljard", woodCost = 4, goldCost = 2, silverCost = 1, woolCost = 3, leatherCost = 1, jewelCost = 1, time = 21, cost = 5400, happiness = 9, prestige = 36, description = "Biljard z draguljem za visoko plemstvo." },
    royal_grand_billiard = { name = "Kraljevski veliki biljard", woodCost = 6, goldCost = 3, silverCost = 2, woolCost = 4, leatherCost = 1, jewelCost = 2, pearlCost = 2, time = 28, cost = 11000, happiness = 15, prestige = 65, description = "Veliki kraljevski biljard z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    billiard_workshop = { name = "Biljardna delavnica", cost = { gold = 280, wood = 180, stone = 120, wool = 6 }, upkeep = 6, qualityBonus = 5 },
    gaming_loft = { name = "Igralna podstrešje", cost = { gold = 1000, wood = 320, stone = 240, silver = 6, leather = 6 }, upkeep = 23, qualityBonus = 18 },
    master_billiard_atelier = { name = "Mojstrski biljardni atelje", cost = { gold = 2800, wood = 380, stone = 480, silver = 32, gold = 6 }, upkeep = 65, qualityBonus = 30 },
    royal_gaming_palace = { name = "Kraljevska igralska palača", cost = { gold = 11800, wood = 600, stone = 760, gold = 75, jewel = 18 }, upkeep = 235, qualityBonus = 55, prestigeBonus = 50 },
}
BilliardMaker.woodStock = 22; BilliardMaker.woolStock = 16; BilliardMaker.leatherStock = 10; BilliardMaker.silverStock = 6; BilliardMaker.goldStock = 6; BilliardMaker.jewelStock = 4; BilliardMaker.pearlStock = 4
BilliardMaker.productStock = {}; BilliardMaker.buildings = {}; BilliardMaker.maker = nil; BilliardMaker.activeMaking = {}; BilliardMaker.totalProducts = 0; BilliardMaker.dayTimer = 0
function BilliardMaker.init() BilliardMaker.woodStock=22; BilliardMaker.woolStock=16; BilliardMaker.leatherStock=10; BilliardMaker.silverStock=6; BilliardMaker.goldStock=6; BilliardMaker.jewelStock=4; BilliardMaker.pearlStock=4; BilliardMaker.productStock={}; BilliardMaker.buildings={}; BilliardMaker.maker=nil; BilliardMaker.activeMaking={}; BilliardMaker.totalProducts=0; BilliardMaker.dayTimer=0; print("[BilliardMaker] Royal Billiard Maker System initialized (6 products, 4 buildings)") end
function BilliardMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BilliardMaker.maker={name=n or ("Biljardar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Biljardar najet: %s (spretnost: %d)",BilliardMaker.maker.name,s),"success") end; return true end
function BilliardMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BilliardMaker.build(id) local ok,e=BilliardMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BilliardMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BilliardMaker.getQualityBonus() local b=0; for _,bd in ipairs(BilliardMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BilliardMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and BilliardMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.woolCost and BilliardMaker.woolStock<(d.woolCost or 0) then return false,"Premalo volne" end; if d.leatherCost and BilliardMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BilliardMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BilliardMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BilliardMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BilliardMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BilliardMaker.buildings==0 then return false,"Potrebna biljardna delavnica" end; if not BilliardMaker.maker then return false,"Potreben biljardar" end; return true end
function BilliardMaker.make(pt,qty) qty=qty or 1; local ok,e=BilliardMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then BilliardMaker.woodStock=BilliardMaker.woodStock-d.woodCost*qty end; if d.woolCost then BilliardMaker.woolStock=BilliardMaker.woolStock-d.woolCost*qty end; if d.leatherCost then BilliardMaker.leatherStock=BilliardMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BilliardMaker.silverStock=BilliardMaker.silverStock-d.silverCost*qty end; if d.goldCost then BilliardMaker.goldStock=BilliardMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BilliardMaker.jewelStock=BilliardMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BilliardMaker.pearlStock=BilliardMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BilliardMaker.maker then t=math.max(1,t-math.floor(BilliardMaker.maker.skill/12)) end; table.insert(BilliardMaker.activeMaking,{id="billiard_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BilliardMaker.completeMaking(m) local q=1.0+(BilliardMaker.getQualityBonus()/100); if BilliardMaker.maker then q=q+(BilliardMaker.maker.skill/140) end; q=math.min(2.5,q); BilliardMaker.productStock[m.productType]=(BilliardMaker.productStock[m.productType] or 0)+m.quantity; BilliardMaker.totalProducts=BilliardMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BilliardMaker.maker then BilliardMaker.maker.itemsMade=BilliardMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BilliardMaker.maker.skill=math.min(100,BilliardMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Biljard izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"billiard.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BilliardMaker.update(dt) if not _G.state then return end; BilliardMaker.dayTimer=BilliardMaker.dayTimer+dt; if BilliardMaker.dayTimer>=30 then BilliardMaker.dayTimer=0; for i=#BilliardMaker.activeMaking,1,-1 do local m=BilliardMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BilliardMaker.completeMaking(m); table.remove(BilliardMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BilliardMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BilliardMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BilliardMaker.getStats() return {woodStock=BilliardMaker.woodStock,woolStock=BilliardMaker.woolStock,leatherStock=BilliardMaker.leatherStock,silverStock=BilliardMaker.silverStock,goldStock=BilliardMaker.goldStock,jewelStock=BilliardMaker.jewelStock,pearlStock=BilliardMaker.pearlStock,productStock=BilliardMaker.productStock,numBuildings=#BilliardMaker.buildings,hasMaker=BilliardMaker.maker~=nil,makerName=BilliardMaker.maker and BilliardMaker.maker.name or "—",makerSkill=BilliardMaker.maker and BilliardMaker.maker.skill or 0,activeMaking=#BilliardMaker.activeMaking,totalProducts=BilliardMaker.totalProducts} end
return BilliardMaker
